import{_ as t,a0 as o,w as d,s as r,I as n,x as a,a1 as p,A as e,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"自動共享和上傳文件到兼容的託管站點 | LCTT x X-CMD","titleTemplate":false,"description":"自動共享和上傳文件到兼容的託管站點 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"自動共享和上傳文件到兼容的託管站點 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"自動共享和上傳文件到兼容的託管站點 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20171027 Share And Upload Files To Compatible Hosting Sites Automatically","title":"自動共享和上傳文件到兼容的託管站點","tag":"201912","desc":""},"relativePath":"201912/20171027 Share And Upload Files To Compatible Hosting Sites Automatically.md","filePath":"[post].md"}'),c={name:"201912/20171027 Share And Upload Files To Compatible Hosting Sites Automatically.md"};function g(h,s,u,f,m,b){const i=o("Link");return d(),r("div",null,[s[23]||(s[23]=n("h1",{id:"自動共享和上傳文件到兼容的託管站點",tabindex:"-1"},[a("自動共享和上傳文件到兼容的託管站點 "),n("a",{class:"header-anchor",href:"#自動共享和上傳文件到兼容的託管站點","aria-label":"Permalink to “自動共享和上傳文件到兼容的託管站點”"},"​")],-1)),s[24]||(s[24]=n("p",null,[n("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/10/Upload-720x340.png",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("前陣子我們寫了一個關於 ",-1)),p(i,{href:"https://www.ostechnix.com/easy-fast-way-share-files-internet-command-line/"},{default:e(()=>[...s[0]||(s[0]=[a("Transfer.sh",-1)])]),_:1}),s[2]||(s[2]=a("的指南，它允許你使用命令列通過互聯網來分享文件。今天，我們來看看另一種文件分享實用工具 Anypaste。這是一個基於文件類型自動共享和上傳文件到兼容託管站點的簡單腳本。你不需要去手動登錄到託管站點來上傳或分享你的文件。Anypaste 將會根據你想上傳的文件的類型來",-1)),s[3]||(s[3]=n("strong",null,"自動挑選合適的託管站點",-1)),s[4]||(s[4]=a("。簡單地説，照片將被上傳到圖像託管站點，視頻被傳到視頻站點，代碼被傳到 pastebin。難道不是很酷的嗎？Anypaste 是一個完全開源、免費、輕量的腳本，你可以通過命令列完成所有操作。因此，你不需要依靠那些臃腫的、需要消耗大量內存的 GUI 應用來上傳和共享文件。",-1))]),s[25]||(s[25]=l(`<h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>正如我所説，這僅僅是一個腳本。所以不存在任何複雜的安裝步驟。只需要將腳本下載後放置在你想要運行的位置（例如 <code>/usr/bin/</code>），並將其設置為可執行文件後就可以直接使用了。此外，你也可以通過下面的這兩條命令來快速安裝 Anypaste。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo curl -o /usr/bin/anypaste https://anypaste.xyz/sh</span></span>
<span class="line"><span>sudo chmod +x /usr/bin/anypaste</span></span></code></pre></div><p>就是這樣簡單。如果需要更新老的 Anypaste 版本，只需要用新的可執行文件覆寫舊的即可。</p><p>現在，讓我們看看一些實例。</p><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h3><p>Anypaste 開箱即用，並不需要特別的配置。默認的配置文件是 <code>~/.config/anypaste.conf</code>，這個文件在你第一次運行 Anypaste 時會自動創建。</p><p>需要配置的選項只有 <code>ap_plugins</code>。Anypaste 使用插件系統上傳文件。每個站點（的上傳）都由一個特定的插件表示。你可以在 <code>anypaste.conf</code> 文件中的 <code>ap-plugins directive</code> 位置瀏覽可用的插件列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># List of plugins</span></span>
<span class="line"><span># If there are multiple compatible plugins, precedence is determined</span></span>
<span class="line"><span># by which one is listed first in this array</span></span>
<span class="line"><span>ap_plugins=(</span></span>
<span class="line"><span># Videos/Gifs</span></span>
<span class="line"><span>&#39;sendvid&#39; &#39;streamable&#39; &#39;gfycat&#39;</span></span>
<span class="line"><span># Images</span></span>
<span class="line"><span>&#39;tinyimg&#39; &#39;vgyme&#39;</span></span>
<span class="line"><span># Audio</span></span>
<span class="line"><span>&#39;instaudio&#39;</span></span>
<span class="line"><span># Text</span></span>
<span class="line"><span>&#39;hastebin&#39; &#39;ixio&#39; &#39;sprunge&#39;</span></span>
<span class="line"><span># Documents</span></span>
<span class="line"><span>&#39;docdroid&#39;</span></span>
<span class="line"><span># Any file</span></span>
<span class="line"><span>&#39;jirafeau&#39; &#39;fileio&#39;</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>如果你要安裝一個新的插件，將它添加進這個列表中就可以了。如果你想禁用一個默認插件，只需要將它從列表中移除即可。如果有多個兼容的插件，排列中的第一個會被選擇，因此<strong>順序很重要</strong>。</p><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>上傳一個簡單的文件，例如 <code>test.png</code>，可以運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>anypaste test.png</span></span></code></pre></div><p>輸出示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Current file: test.png</span></span>
<span class="line"><span>Attempting to upload with plugin &#39;tinyimg&#39;</span></span>
<span class="line"><span>######################################################################## 100.0%</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Direct Link: https://tinyimg.io/i/Sa1zsjj.png</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Upload complete.</span></span>
<span class="line"><span>All files processed. Have a nice day!</span></span></code></pre></div>`,15)),n("p",null,[s[6]||(s[6]=a("正如輸出結果中所看到的，Anypaste 通過自動匹配圖像文件 ",-1)),s[7]||(s[7]=n("code",null,"test.png",-1)),s[8]||(s[8]=a(" 發現了兼容的託管站點（",-1)),p(i,{href:"https://tinyimg.io"},{default:e(()=>[...s[5]||(s[5]=[a("https://tinyimg.io",-1)])]),_:1}),s[9]||(s[9]=a("），並將文件上傳到了該站點。此外，Anypaste 也為我們提供了用於直接瀏覽/下載該文件的鏈接。",-1))]),s[26]||(s[26]=l(`<p>不僅是 png 格式文件，你還可以上傳任何其他圖片格式的文件。例如，下面的命令將會上傳 gif 格式文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ anypaste file.gif</span></span>
<span class="line"><span>Current file: file.gif</span></span>
<span class="line"><span>Plugin &#39;streamable&#39; is compatible, but missing config parameters: &#39;streamable_email&#39; &#39;streamable_password&#39;</span></span>
<span class="line"><span>You can set them in /home/sk/.config/anypaste.conf</span></span>
<span class="line"><span>Attempting to upload with plugin &#39;gfycat&#39;</span></span>
<span class="line"><span>######################################################################## 100.0%</span></span>
<span class="line"><span>Reminder: Gfycat needs time to encode. Your video will not appear right away.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Link: https://gfycat.com/MisguidedQuaintBergerpicard</span></span>
<span class="line"><span>Direct(ish) Link: https://thumbs.gfycat.com/MisguidedQuaintBergerpicard-size_restricted.gif</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Upload complete.</span></span>
<span class="line"><span>All files processed. Have a nice day!</span></span></code></pre></div><p>你可以將鏈接分享給你的家庭、朋友和同事們。下圖是我剛剛將圖片上傳到 gfycat 網站的截圖。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/10/gfycat.png" alt=""></p><p>也可以一次同時上傳多個（相同格式或不同格式）文件。</p><p>下面的例子提供參考，這裏我會上傳兩個不同的文件，包含一個圖片文件和一個視頻文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>anypaste image.png video.mp4</span></span></code></pre></div><p>輸出示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Current file: image.png</span></span>
<span class="line"><span>Attempting to upload with plugin &#39;tinyimg&#39;</span></span>
<span class="line"><span>######################################################################## 100.0%</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Direct Link: https://tinyimg.io/i/au1PHpg.png</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Upload complete.</span></span>
<span class="line"><span>Current file: video.mp4</span></span>
<span class="line"><span>Plugin &#39;streamable&#39; is compatible, but missing config parameters: &#39;streamable_email&#39; &#39;streamable_password&#39;</span></span>
<span class="line"><span>You can set them in /home/sk/.config/anypaste.conf</span></span>
<span class="line"><span>Attempting to upload with plugin &#39;sendvid&#39;</span></span>
<span class="line"><span>######################################################################## 100.0%</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Link: http://sendvid.com/wwy7w96h</span></span>
<span class="line"><span>Delete/Edit: http://sendvid.com/wwy7w96h?secret=39c0af2d-d8bf-4d3d-bad3-ad37432a40a5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Upload complete.</span></span>
<span class="line"><span>All files processed. Have a nice day!</span></span></code></pre></div><p>Anypaste 針對兩個文件自動發現了與之相兼容的託管站點併成功上傳。</p><p>正如你在上述用法介紹部分的例子中注意到的，Anypaste 會自動挑選最佳的插件。此外，你可以指定插件進行文件上傳，這裏提供一個上傳到 gfycat 的案例，運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>anypaste -p gfycat file.gif</span></span></code></pre></div><p>輸出示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Current file: file.gif</span></span>
<span class="line"><span>Plugin &#39;streamable&#39; is compatible, but missing config parameters: &#39;streamable_email&#39; &#39;streamable_password&#39;</span></span>
<span class="line"><span>You can set them in /home/sk/.config/anypaste.conf</span></span>
<span class="line"><span>Attempting to upload with plugin &#39;gfycat&#39;</span></span>
<span class="line"><span>######################################################################## 100.0%</span></span>
<span class="line"><span>Reminder: Gfycat needs time to encode. Your video will not appear right away.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Link: https://gfycat.com/GrayDifferentCollie</span></span>
<span class="line"><span>Direct(ish) Link: https://thumbs.gfycat.com/GrayDifferentCollie-size_restricted.gif</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Upload complete.</span></span>
<span class="line"><span>All files processed. Have a nice day!</span></span></code></pre></div><p>如果要使用特定插件進行文件上傳，可以通過以下命令繞過兼容性檢查：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>anypaste -fp gfycat file.gif</span></span></code></pre></div><p>如果你發現在配置文件中忽略了特定的插件，你仍然可以強制 Anypaste 去使用特定的插件，只不過需要加上 <code>-xp</code> 參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>anypaste -xp gfycat file.gif</span></span></code></pre></div><p>如果想要以交互模式上傳文件，可以在命令後加上 <code>-i</code> 標籤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ anypaste -i file.gif</span></span>
<span class="line"><span>Current file: file.gif</span></span>
<span class="line"><span>Determine compatible plugins automatically? [Y/n] **n**</span></span>
<span class="line"><span>The following plugins were found: &#39;sendvid&#39; &#39;streamable&#39; &#39;gfycat&#39; &#39;tinyimg&#39; &#39;vgyme&#39; &#39;instaudio&#39; &#39;hastebin&#39; &#39;ixio&#39; &#39;sprunge&#39; &#39;docdroid&#39; &#39;jirafeau&#39; &#39;fileio&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Enter the (partial) name of a plugin, or nothing for automatic selection</span></span>
<span class="line"><span>**gfycat**</span></span>
<span class="line"><span>Attempt to upload with plugin &#39;gfycat&#39;? [Y/n] **y**</span></span>
<span class="line"><span>Attempting to upload with plugin &#39;gfycat&#39;</span></span>
<span class="line"><span>######################################################################## 100.0%</span></span>
<span class="line"><span>Reminder: Gfycat needs time to encode. Your video will not appear right away.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Link: https://gfycat.com/WaryAshamedBlackbear</span></span>
<span class="line"><span>Direct(ish) Link: https://thumbs.gfycat.com/WaryAshamedBlackbear-size_restricted.gif</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Upload complete.</span></span>
<span class="line"><span>All files processed. Have a nice day!</span></span></code></pre></div><p>正如你所見，Anypaste 首先詢問了我是否需要自動確定插件。因為我不想自動尋找插件，所以我回復了 “No”。之後，Anypaste 列出了所有可選擇的插件，並要求我從列表中選擇一個。同樣的，你可以上傳和共享不同類型的文件，相關文件會被上傳到相兼容的站點。</p><p>無論你何時上傳一個視頻文件，Anypaste 都會將其上傳到以下站點中的一個：</p><ol><li>sendvid</li><li>streamable</li><li>gfycat</li></ol><p>這裏注意列表順序，Anypaste 將首先將文件上傳到 sendvid 站點，如果沒有 sendvid 的插件可供使用，Anypaste 將會嘗試順序中的另外兩個站點。當然你也可以通過更改配置文件來修改順序。</p><p>圖像文件上傳站點：</p><ol><li>tinyimg.io</li><li>vgy.me</li></ol><p>音頻文件上傳站點：</p><ol><li>instaud</li></ol><p>文本文件上傳站點：</p><ol><li>hastebin</li><li>ix.io</li><li>sprunge.us</li></ol><p>文檔上傳站點：</p><ol><li>docdroid</li></ol><p>其他任意類型的文件上傳站點：</p><ol><li>jirafeau</li><li>file.io</li></ol><p>上面列出來的部分站點一段特定的時間後會刪除上傳的內容，所以在上傳和分享內容時應先明確這些站點的條款和條件。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>在我看來，識別文件並決定將其上傳到何處的想法非常棒，而且開發者也以恰當的方式完美地實現了它。毫無疑問，Anypaste 對那些在互聯網上需要頻繁分享文件的人們非常有用，我希望你也能這麼覺得。</p><p>這就是今天的全部內容，後面會有越來越多的好東西分享給大家。再見啦！</p><hr>`,39)),n("p",null,[s[11]||(s[11]=a("via: ",-1)),p(i,{href:"https://www.ostechnix.com/anypaste-share-upload-files-compatible-hosting-sites-automatically/"},{default:e(()=>[...s[10]||(s[10]=[a("https://www.ostechnix.com/anypaste-share-upload-files-compatible-hosting-sites-automatically/",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("作者：",-1)),p(i,{href:"https://www.ostechnix.com/author/sk/"},{default:e(()=>[...s[12]||(s[12]=[a("SK",-1)])]),_:1}),s[16]||(s[16]=a(" 譯者：",-1)),p(i,{href:"https://github.com/lixin555"},{default:e(()=>[...s[13]||(s[13]=[a("lixin555",-1)])]),_:1}),s[17]||(s[17]=a(" 校對：",-1)),p(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[20]||(s[20]=a("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原創編譯，",-1)),p(i,{href:"https://linux.cn/"},{default:e(()=>[...s[19]||(s[19]=[a("Linux中國",-1)])]),_:1}),s[22]||(s[22]=a(" 榮譽推出",-1))])])}const v=t(c,[["render",g]]);export{C as __pageData,v as default};
